  id=id||`half-stitch-${a.id.slice(0,40)}-${b.id.slice(0,40)}`;name=name||(a.name+' ↔ '+b.name).slice(0,300);const metas=originals.map(c=>c.data.meta),meta={title:name,source:`A: ${raw(a.name)} | B: ${raw(b.name)}`,sourceKey:'half-stitch:'+id,units:'m',axis:{up:'z'},isDemo:metas.some(m=>m.isDemo),halfCar:false,scalarMirror:false,ranges:Object.fromEntries(['Cp','CpT'].map(f=>[f,[Math.min(...metas.map(m=>m.ranges[f][0])),Math.max(...metas.map(m=>m.ranges[f][1]))]])),surfaceRange:[Math.min(...metas.map(m=>m.surfaceRange[0])),Math.max(...metas.map(m=>m.surfaceRange[1]))],comparison:{kind:'half-car-stitch',version:1,sources,sectionPolicy:'common-x-no-interpolation',sectionsStatus:sections.length?'shared':pairs.length?'no-common-fields':'no-common-x',sourceSectionXs:originals.map(c=>c.data.sections.map(s=>s.x)),coefficientReferences:metas.map(m=>clone(m.coefficientReference??null))}};for(const key of ['fieldLabels','fieldUnits'])if(key in metas[0])meta[key]=clone(metas[0][key]);return validateCase({schema:'cfd-review-case',version:1,id,name,data:{meta,parts,sections,layers}});
