 // JSON.parse establishes syntax first. This scan only rejects duplicate keys,
 // including escaped spellings such as "name" and "\u006eame".
 function parseJsonStrict(input){
  const raw=input.replace(/^\uFEFF/,''),parsed=JSON.parse(raw),stack=[];
  const tokens=/"(?:\\[\s\S]|[^"\\])*"|[{}\[\],]/g;
  let match;
  while((match=tokens.exec(raw))){
   const token=match[0],top=stack[stack.length-1];
   if(token==='{')stack.push({keys:new Set(),expectKey:true});
   else if(token==='['){const end=raw.indexOf(']',tokens.lastIndex);if(end>=0&&/^[\dEe+.,\s-]*$/.test(raw.slice(tokens.lastIndex,end)))tokens.lastIndex=end+1;else stack.push(null);}
   else if(token==='}'||token===']')stack.pop();
   else if(token===','){if(top)top.expectKey=true;}
   else if(top?.expectKey){const key=JSON.parse(token);assert(!top.keys.has(key),tr`JSON 包含重复对象键：${key}`);top.keys.add(key);top.expectKey=false;}
  }
  return parsed;
 }
