    if(numericValues>JSON_NUMERIC_LIMIT)throw new Error(tr`JSON 数值数据 ${numericValues.toLocaleString('en-US')} 项超过 ${JSON_NUMERIC_LIMIT.toLocaleString('en-US')}；请减少导出范围、截面、图层或拆分工况`);
    assert(depth+1<=JSON_MAX_DEPTH,tr`JSON 嵌套深度 ${depth+1} 超过 ${JSON_MAX_DEPTH}`);
