 function validateProject(p){jsonGuard(p);assert(obj(p)&&p.schema==='cfd-review-project'&&p.version===1,tr('须为 cfd-review-project version 1'));text(p.title,tr('工程名称'));assert(Array.isArray(p.cases)&&p.cases.length>0&&p.cases.length<=32,tr('须提供 1 至 32 个工况'));const ids=new Set();for(const c of p.cases){validateCase(c);assert(!ids.has(c.id),tr('工况 ID 重复'));ids.add(c.id);}for(const c of p.cases)if(c.data.meta.comparison)validateComposition(c,p.cases);if(p.ui!==undefined){assert(obj(p.ui),tr('工程界面设置须为对象'));if(p.ui.language!==undefined)assert(['en','zh-CN'].includes(p.ui.language),tr('工程语言须为 en 或 zh-CN'));if(p.ui.sidebarCollapsed!==undefined)assert(typeof p.ui.sidebarCollapsed==='boolean',tr('目录折叠状态须为布尔值'));}assert(Array.isArray(p.views)&&p.views.length>0&&p.views.length<=2,tr('须提供 1 或 2 个视口'));for(const v of p.views){assert(obj(v)&&ids.has(v.caseId),tr('视口引用的工况不存在'));if(v.state!==null&&v.state!==undefined)validateState(v.state,p.cases.find(c=>c.id===v.caseId));}assert(obj(p.links)&&['camera','section','field','color'].every(k=>typeof p.links[k]==='boolean'),tr('联动开关须为布尔值'));assert(p.notes===undefined||Array.isArray(p.notes)&&p.notes.length<=2000,tr('批注数量超过 2000 或格式无效'));const noteIds=new Set();for(const n of p.notes||[]){text(n.id,tr('批注 ID'),128);text(n.text,tr('批注内容'),12000);assert(!noteIds.has(n.id),tr('批注 ID 重复'));noteIds.add(n.id);assert(ids.has(n.caseId)&&Number.isInteger(n.view)&&n.view>=0&&n.view<p.views.length,tr('批注工况或视口不存在'));validateState(n.state,p.cases.find(c=>c.id===n.caseId));}return p;}
