  const flush=()=>{if(!buffer)return;const part=new Blob([buffer]);bytes+=part.size;assert(bytes<=limit,limit===MAX_RECIPE_BYTES?tr('半车拼接索引超过 1 MiB'):tr('单工况或工程索引超过 500 MiB；请减少对应截面、图层或批注'));parts.push(part);buffer='';};
